import puppeteer from 'puppeteer-core';
import assert from 'node:assert/strict';
const base=process.env.TEST_URL,exe=process.env.CHROME_PATH;if(!base||!exe)throw Error('TEST_URL/CHROME_PATH missing');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const browser=await puppeteer.launch({executablePath:exe,headless:true,args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage'],timeout:30000});
const contexts=[];
async function wait(fn,msg,ms=10000){const end=Date.now()+ms;while(Date.now()<end){try{if(await fn())return}catch{}await sleep(60)}throw Error(msg)}
async function client(name,score=100){const ctx=await browser.createBrowserContext(),p=await ctx.newPage();contexts.push(ctx);const errors=[];p.on('pageerror',e=>errors.push(String(e.stack||e)));p.on('console',m=>{if(m.type()==='error'&&!/Failed to load resource.*404/i.test(m.text()))errors.push(m.text())});await p.evaluateOnNewDocument(({name,score})=>{localStorage.setItem('BombermanPlayerName',name);localStorage.setItem('BombermanRatingV1',String(score));localStorage.setItem('BombermanScoreV1Initialized','1');localStorage.removeItem('BombermanBestOfV130');localStorage.removeItem('BombermanRivalriesV130');if(navigator.serviceWorker)navigator.serviceWorker.register=()=>Promise.resolve({})},{name,score});await p.goto(base,{waitUntil:'domcontentloaded',timeout:20000});await p.waitForFunction(()=>window.BomberSocial130?.version==='v0.13.0'&&window.BomberMultiplayer?.ready&&window.BomberLeaderboard127&&gGameEngine?.menu,{timeout:30000});return{p,errors}}
function noSyntheticWords(text){return !/(simulated|fake[- ]?human)/i.test(String(text||''))}
let solo,A,B;
try{
 solo=await client('ColeSocial',100);const p=solo.p;
 const ui=await p.evaluate(()=>({version:BomberSocial130.version,best:BomberSocial130.getBestOf(),buttons:[...document.querySelectorAll('[data-v130-best]')].map(x=>x.textContent.trim())}));
 assert.equal(ui.version,'v0.13.0');assert.equal(ui.best,1);assert.deepEqual(ui.buttons,['1 Round','Best of 3','Best of 5']);
 await p.evaluate(()=>BomberSocial130.setBestOf(3));assert.equal(await p.evaluate(()=>localStorage.getItem('BombermanBestOfV130')),'3');
 await p.evaluate(()=>BomberLeaderboard127.open());await sleep(150);let visible=await p.evaluate(()=>document.getElementById('v127LeaderboardPanel').innerText);assert.ok(noSyntheticWords(visible),'leaderboard exposes synthetic-opponent wording: '+visible);await p.click('#v127LeaderboardPanel .v127_lb_close');
 await p.evaluate(()=>{B115.kind='public';B115.setRole('host');B115.startSimulated()});await wait(()=>p.evaluate(()=>B115.role==='simulated'&&!!gGameEngine.simulatedOpponent),'public fallback did not start',10000);await sleep(300);
 let match=await p.evaluate(()=>({status:B115.els.matchStatus.textContent,profile:BomberLeaderboard127.profile(B115.remoteName),opp:B115.remoteName}));assert.ok(/^PUBLIC/.test(match.status));assert.ok(noSyntheticWords(match.status));assert.ok(match.profile&&match.status.includes('(#'+match.profile.displayRank+')'));
 await p.evaluate(()=>BomberSocial130.debug.setRival(2,1));await p.evaluate(()=>gGameEngine.restart());await wait(()=>p.evaluate(()=>!document.getElementById('v130Rival').hidden),'RIVAL MATCH banner missing');let rivalText=await p.$eval('#v130Rival',e=>e.innerText);assert.match(rivalText,/RIVAL MATCH/);assert.match(rivalText,/2–1/);
 await p.evaluate(()=>{const g=gGameEngine,me=g.players[0],op=g.simulatedOpponent;me.bmp.x=32;me.bmp.y=32;me.updatePosition();const b=new Bomb({x:1,y:2},1);b.owner=op;b.endTime=Date.now()+350;g.stage.addChild(b.bmp);g.bombs.push(b);op.bombs.push(b);window.__v130ClutchBomb=b});await sleep(170);await p.evaluate(()=>{const me=gGameEngine.players[0];me.bmp.x=64;me.bmp.y=32;me.updatePosition();window.__v130ClutchBomb.explode()});await wait(()=>p.evaluate(()=>BomberSocial130.stats().p0.clutches>=1),'clutch was not detected');assert.match(await p.$eval('#v130Toast',e=>e.textContent),/CLUTCH/i);
 await p.evaluate(()=>{const g=gGameEngine,k=g.players[0],v=g.simulatedOpponent,b=new Bomb({x:v.position.x,y:v.position.y},1);b.owner=k;b.exploded=true;b.fires=[{position:{x:v.position.x,y:v.position.y},bmp:null}];g.bombs.push(b);v.die();Utils.removeFromArray(g.bombs,b)});
 await wait(()=>p.evaluate(()=>BomberSocial130.set()?.localWins===1),'best-of-3 round was not recorded');
 let social=await p.evaluate(()=>({set:BomberSocial130.set(),rival:BomberSocial130.rivalry(),stats:BomberSocial130.stats(),kill:document.getElementById('v130Toast').textContent}));assert.equal(social.set.bestOf,3);assert.equal(social.set.localWins,1);assert.equal(social.set.opponentWins,0);assert.equal(social.set.complete,false);assert.equal(social.rival.wins,3);assert.equal(social.rival.losses,1);assert.equal(social.stats.p0.kills,1);assert.match(social.stats.lastKill,/eliminated/);
 await p.evaluate(()=>BomberQOL.showPostMatch('Round over'));await sleep(120);let post=await p.evaluate(()=>({visible:!document.getElementById('qolPostMatch').hidden,rows:document.querySelectorAll('#v130PostStats .v130_stats_row').length,text:document.getElementById('v130PostStats').textContent||'',body:document.body.innerText}));console.log('POST_STATS',JSON.stringify(post));assert.equal(post.visible,true);assert.equal(post.rows,2);for(const word of ['Elims','Bombs','Blocks','Items','Clutch'])assert.ok(post.text.includes(word),'missing '+word+' in post stats: '+post.text);assert.ok(post.text.includes('3–1'));assert.ok(noSyntheticWords(post.body),'visible UI exposes simulated/fake-human wording');console.log('FAKE_RIVAL_STATS_CLUTCH_SET PASS',JSON.stringify(social.set));
 A=await client('HostSocial',100);B=await client('GuestSocial',100);await A.p.evaluate(()=>BomberSocial130.setBestOf(5));const id='bomberman-v130-'+Date.now();
 await A.p.evaluate(id=>{BomberV124.setAIEnabled(false);B115.privateId=()=>id;B115.els.privateCode.value='9';B115.els.name.value='HostSocial';B115.startPrivateHost()},id);await sleep(800);await B.p.evaluate(id=>{B115.privateId=()=>id;B115.els.privateCode.value='9';B115.els.name.value='GuestSocial';B115.startPrivateJoin()},id);
 await wait(()=>B.p.evaluate(()=>BomberDataSync.role==='guest'&&!!BomberMultiplayer.roundId),'v0.12.9 pair did not connect',30000);await wait(async()=>{const [a,b]=await Promise.all([A.p.evaluate(()=>BomberSocial130.set()),B.p.evaluate(()=>BomberSocial130.set())]);return a?.bestOf===5&&b?.bestOf===5},'host best-of-5 did not sync');
 assert.equal(await A.p.evaluate(()=>BomberMultiplayer.version),'v0.12.9');assert.equal(await B.p.evaluate(()=>BomberMultiplayer.version),'v0.12.9');
 await A.p.evaluate(()=>gGameEngine.players[1].die());
 await wait(async()=>{const [a,b]=await Promise.all([A.p.evaluate(()=>BomberSocial130.set()),B.p.evaluate(()=>BomberSocial130.set())]);return a?.localWins===1&&a?.opponentWins===0&&b?.localWins===0&&b?.opponentWins===1},'set perspective did not sync correctly');
 await wait(()=>B.p.evaluate(()=>BomberSocial130.stats().p1.deaths>=1),'guest did not receive authoritative round stats');
 await wait(async()=>{const [a,b]=await Promise.all([A.p.evaluate(()=>BomberSocial130.rivalry()),B.p.evaluate(()=>BomberSocial130.rivalry())]);return a?.wins===1&&b?.losses===1},'rivalry perspective did not persist on both clients');
 const real=await Promise.all([A.p,B.p].map(x=>x.evaluate(()=>({set:BomberSocial130.set(),rival:BomberSocial130.rivalry(),stats:BomberSocial130.stats(),status:B115.els.matchStatus.textContent,version:BomberMultiplayer.version}))));assert.equal(real[0].rival.wins,1);assert.equal(real[1].rival.losses,1);assert.ok(real.every(x=>x.version==='v0.12.9'));assert.ok(real.every(x=>noSyntheticWords(x.status)));assert.ok(real[0].set.opponent==='GuestSocial'&&real[1].set.opponent==='HostSocial');console.log('REAL_RIVAL_SET_SYNC PASS',JSON.stringify(real.map(x=>x.set)));
 const allErrors=[...solo.errors,...A.errors,...B.errors];if(allErrors.length)throw Error('browser errors: '+allErrors.join(' | '));console.log('V130_SOCIAL_SMOKE PASS');
}finally{for(const c of contexts)await c.close().catch(()=>{});await browser.close().catch(()=>{})}